import * as React from "react";
import * as ReactDom from "react-dom";
import { BaseClientSideWebPart, IPropertyPaneConfiguration, PropertyPaneToggle, PropertyPaneSlider } from "@microsoft/sp-webpart-base";
import MoreForYou from "./components/MoreForYou";

export interface IMoreForYouWebPartProps {
  take: number;
  randomizeAcrossDepartment: boolean;
}

export default class MoreForYouWebPart extends BaseClientSideWebPart<IMoreForYouWebPartProps> {
  public render(): void {
    const element = React.createElement(MoreForYou, {
      context: this.context,
      take: this.properties.take ?? 4,
      randomizeAcrossDepartment: this.properties.randomizeAcrossDepartment ?? true
    });

    ReactDom.render(element, this.domElement);
  }

  protected onInit(): Promise<void> {
    if (typeof this.properties.take !== "number") this.properties.take = 4;
    if (typeof this.properties.randomizeAcrossDepartment !== "boolean")
      this.properties.randomizeAcrossDepartment = true;
    return Promise.resolve();
  }

  protected getPropertyPaneConfiguration(): IPropertyPaneConfiguration {
    return {
      pages: [
        {
          header: { description: "More For You settings" },
          groups: [
            {
              groupName: "Display",
              groupFields: [
                PropertyPaneSlider("take", { label: "Number of tiles", min: 2, max: 12, step: 1 }),
                PropertyPaneToggle("randomizeAcrossDepartment", { label: "Only from current page's department" })
              ]
            }
          ]
        }
      ]
    };
  }
}
