import { SPFI } from "@pnp/sp";
import "@pnp/sp/fields"; // << make sure .fields works
import { DEPT_HIDDEN_TEXT_FIELD_ID } from "../../components/TS/constants";

const CACHE_KEY = "mf_dept_note_internalname";

/**
 * Resolve the hidden Note field **InternalName** for the NADepartment taxonomy column on Site Pages.
 * Strategy:
 *  1) sessionStorage cache
 *  2) If DEPT_HIDDEN_TEXT_FIELD_ID (GUID) is provided -> fields.getById(GUID).InternalName
 *  3) Auto-discover: fields.getByInternalNameOrTitle('NADepartment').TextField (GUID) -> fields.getById(GUID).InternalName
 */
export async function resolveDeptNoteInternalName(
  sp: SPFI,
  listTitle = "Site Pages"
): Promise<string | null> {
  try {
    // 1) cache
    const cached = sessionStorage.getItem(CACHE_KEY);
    if (cached) return cached;

    // 2) GUID override path
    if (DEPT_HIDDEN_TEXT_FIELD_ID) {
      const note = await sp.web.lists
        .getByTitle(listTitle)
        .fields.getById(DEPT_HIDDEN_TEXT_FIELD_ID)
        .select("InternalName")();

      const internal = (note as any)?.InternalName as string | undefined;
      if (internal) {
        sessionStorage.setItem(CACHE_KEY, internal);
        return internal;
      }
    }

    // 3) auto-discover via taxonomy.TextField GUID
    // IFieldInfo doesn't declare TextField, so treat as any
    const tax: any = await sp.web.lists
      .getByTitle(listTitle)
      .fields.getByInternalNameOrTitle("NADepartment")
      .select("TextField")(); // GUID of hidden note field

    const textFieldId: string | null = tax?.TextField || null;
    if (!textFieldId) return null;

    const note2: any = await sp.web.lists
      .getByTitle(listTitle)
      .fields.getById(textFieldId)
      .select("InternalName")();

    const internal2 = note2?.InternalName as string | undefined;
    if (internal2) {
      sessionStorage.setItem(CACHE_KEY, internal2);
      return internal2;
    }
    return null;
  } catch (e) {
    console.warn("resolveDeptNoteInternalName failed:", e);
    return null;
  }
}
